{
  "technical_and_design_decisions": [
    "Migrate wiki into the project repository as Markdown files versioned with the code, rather than using an external wiki system.",
    "Store Hadoop namenode specifics in a centralized XD configuration file (e.g., hadoop.properties) and inject into DSL session context via Spring Environment.",
    "Implement jdbchdfs passthrough using a Spring Batch Tasklet that streams data directly, avoiding chunk-oriented ItemReader/ItemWriter overhead.",
    "Fix execution context coupling in Spring Batch core by separating lifecycle management, then consume the fix in XD via version upgrade and removal of XD-2486 workaround.",
    "Enable Java Config job modules by scanning uploaded module jars for @Configuration classes and Job beans, registering them in XD's job registry.",
    "Design a pluggable SPI (Service Provider Interface) for container orchestration with a core interface and a Receptor API implementation to replace Lattice-specific code.",
    "Add a shortDescription attribute to the module metadata model and documentation generation pipeline.",
    "Extend the shell processor's script resource loader to support HDFS URIs using the Hadoop FileSystem API."
  ],
  "assumptions": [
    "The software increment targets the Spring XD codebase and, where needed, the Spring Batch codebase, as inferred from the user stories.",
    "The developer has appropriate commit/write access to both the XD and Spring Batch repositories to apply fixes and upgrades.",
    "Existing build, test, and CI infrastructure are available and do not require significant modification.",
    "Wiki content is of moderate size (around 50 pages) and can be migrated in roughly one working day.",
    "Hadoop/HDFS cluster credentials and connectivity are already configured in the target environment, so only client-side code changes are needed.",
    "No new user interface screens are required; changes are limited to configuration, backend code, and documentation.",
    "Effort estimates include writing unit/integration tests but exclude separate QA, production deployment, and project management overhead."
  ],
  "activities": [
    {
      "activity_id": "U1-WIKI",
      "activity_name": "Migrate wiki to project repo",
      "activity_description": "Export existing wiki content, convert to Markdown, commit into project repository alongside code so it can be tagged and versioned, and verify links.",
      "most_likely_effort": 8
    },
    {
      "activity_id": "U2-NAMENODE-CFG",
      "activity_name": "Add Hadoop namenode default configuration",
      "activity_description": "Introduce namenode properties in XD config file and implement auto-configuration logic so new DSL sessions automatically pick up namenode location without manual per-session pointing.",
      "most_likely_effort": 12
    },
    {
      "activity_id": "U3-JDBCHDFS-PASS",
      "activity_name": "Implement jdbchdfs passthrough mode",
      "activity_description": "Modify the jdbchdfs batch job to support a passthrough mode that bypasses chunk processing, streaming JDBC data directly to HDFS via a Tasklet, including parameter handling and tests.",
      "most_likely_effort": 24
    },
    {
      "activity_id": "U4-BATCH-FIX",
      "activity_name": "Decouple execution context in Spring Batch",
      "activity_description": "Implement and test the core fix in Spring Batch to decouple execution context from job launch lifecycle, preventing classloader and serialization errors, preparing a release candidate.",
      "most_likely_effort": 40
    },
    {
      "activity_id": "U4-XD-REFACTOR",
      "activity_name": "Upgrade XD to patched Batch and refactor XD-2486",
      "activity_description": "Update Spring XD dependency to the new Spring Batch release, remove the temporary XD-2486 workaround, and run regression tests to ensure job launching works.",
      "most_likely_effort": 24
    },
    {
      "activity_id": "U5-JAVACONFIG",
      "activity_name": "Support Java Config custom job modules",
      "activity_description": "Fix XD module deployment/launch to recognize and register custom job modules defined via Java Config (e.g., @Configuration with Job bean) so the 'job doesn't exist' error is resolved; add integration tests.",
      "most_likely_effort": 32
    },
    {
      "activity_id": "U6-SPI-DESIGN",
      "activity_name": "Design pluggable SPI for container orchestration",
      "activity_description": "Create design for a general pluggable SPI that abstracts container orchestration (Lattice/Diego, etc.), with Receptor API as one implementation, including interface definitions and documentation.",
      "most_likely_effort": 20
    },
    {
      "activity_id": "U6-SPI-CORE",
      "activity_name": "Implement SPI core interfaces",
      "activity_description": "Implement the core SPI interfaces and wiring in XD, enabling alternative orchestration providers to be plugged in via configuration/DI.",
      "most_likely_effort": 24
    },
    {
      "activity_id": "U6-RECEPTOR",
      "activity_name": "Implement Receptor API SPI implementation",
      "activity_description": "Provide the Receptor API as a concrete implementation of the new SPI, demonstrating the PoC on XD-on-Lattice/Diego, with basic tests.",
      "most_likely_effort": 16
    },
    {
      "activity_id": "U7-DOCS",
      "activity_name": "Add shortDescription to module docs",
      "activity_description": "Update module metadata model and documentation templates to include a shortDescription field for all modules, and backfill existing module docs.",
      "most_likely_effort": 16
    },
    {
      "activity_id": "U8-PYHDFS",
      "activity_name": "Host/read Python scripts from HDFS",
      "activity_description": "Extend shell processor script resolution to support HDFS-stored Python scripts (hdfs:// URIs), enabling XD on CF to delegate to Python runtime and capture feedback; includes auth and streaming.",
      "most_likely_effort": 20
    }
  ],
  "reported_total": {
    "most_likely_effort": 236
  }
}

